/**
 * Today's moment, decided: loaded only once Today has something to decide,
 * so the engine, the claim and the words stay off Today's first paint
 * (`useTodayMoment` starts loading this as Today first renders).
 */
import type { LanguageCode } from '@lexpad/core';
import type { ApiBillingState } from '@/api/types.js';
import { db, getMeta } from '@/db/schema.js';
import { TRIAL_MIDWAY_AFTER_DAYS, runningTrial, trialSince, trialVoiced } from '@/features/billing/trial.js';
import { lastPractisedBefore } from '@/features/learn/state.js';
import { momentCopy, type MomentCopy } from './copy.js';
import { NOTHING, pickToday, type Pick } from './moments.js';
import { claimPick, clearPendingWords, isYoung, wordsNoted, wordsWaiting } from './state.js';

const DAY_MS = 86_400_000;

/** Whether `now` is a whole number (≥ 1) of years after `then`, by the local calendar. */
export function yearsToday(then: Date, now: Date): number {
  if (then.getMonth() !== now.getMonth() || then.getDate() !== now.getDate()) return 0;
  return Math.max(0, now.getFullYear() - then.getFullYear());
}

export interface TodayInput {
  today: number;
  /** Cards answered today. */
  doneToday: number;
  streak: number;
  frozenDays: readonly number[];
  notebook: { targetLang: LanguageCode; meaningLang: LanguageCode } | undefined;
  /** The plan, when it was in hand as this visit began; a trial moment never arrives late. */
  billing: ApiBillingState | null;
}

export interface TodayDecision {
  pick: Pick;
  main?: MomentCopy;
  line?: MomentCopy;
}

/** Today's moment for this visit, claimed; nothing when there is none. */
export async function decideToday(input: TodayInput): Promise<TodayDecision> {
  // A save just made may still be counting its words milestone.
  await wordsNoted();
  const state = await getMeta('celebrate');
  if (state === null) return { pick: NOTHING };
  const now = new Date();
  const [user, notes, first, lastBefore] = await Promise.all([
    getMeta('user'),
    getMeta('trialNotes'),
    db.words.orderBy('createdAt').first(),
    lastPractisedBefore(input.today),
  ]);
  const running = runningTrial(input.billing, now);
  // A trial is new to this account if it started after this device began
  // celebrating, or the account was new then (a trial given at sign-up);
  // and only before its midway card is due, which says it from then on.
  const firstSeen = notes.firstSeen === undefined ? undefined : Date.parse(notes.firstSeen);
  const since = trialSince(user?.createdAt, notes);
  const trial =
    running !== undefined &&
    (state.youngAtSettle || firstSeen === undefined || firstSeen >= Date.parse(state.settledAt)) &&
    since !== undefined &&
    now.getTime() - since.getTime() < TRIAL_MIDWAY_AFTER_DAYS * DAY_MS &&
    !isYoung(user?.createdAt, now) &&
    trialVoiced(input.billing, input.notebook?.targetLang, input.notebook?.meaningLang)
      ? { endsAt: running.key }
      : undefined;
  const created = first === undefined ? undefined : new Date(first.createdAt);
  const years = created === undefined ? 0 : yearsToday(created, now);
  const words = wordsWaiting(state, input.today);
  const pick = pickToday(
    {
      words,
      frozenDays: input.frozenDays,
      streak: input.streak,
      trial,
      anniversary:
        years > 0 && first !== undefined
          ? {
              years,
              year: now.getFullYear(),
              word: { id: first.id, headword: first.headword, notebookId: first.notebookId },
            }
          : undefined,
      lastPractised: input.doneToday > 0 ? input.today : lastBefore,
    },
    { today: input.today, young: isYoung(user?.createdAt, now), off: state.off, spent: new Set(state.spent) },
  );
  // A words milestone is said today or never.
  if (state.pendingWords !== null) await clearPendingWords();
  const claimed = await claimPick(pick, input.today);
  const langOf = (): LanguageCode => input.notebook?.targetLang ?? 'en';
  const main = claimed.main === undefined ? undefined : momentCopy(claimed.main, langOf);
  const lineMoment = claimed.main?.size === 'line' ? claimed.main : claimed.extra;
  const line =
    lineMoment === undefined
      ? undefined
      : lineMoment === claimed.main
        ? main
        : momentCopy(lineMoment, langOf);
  return {
    pick: claimed,
    ...(main === undefined ? {} : { main }),
    ...(line === undefined ? {} : { line }),
  };
}
